          "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main() {\ncout << string(\"foo\") + \"bar\" << endl;\nreturn 0;\n}\n",
          "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main() {\ncout << string(\"Hello\") + \"World\" << endl;\nreturn 0;\n}\n"
