          "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main() {\nvector<int> nums = {10, 20, 30};\nint s = accumulate(nums.begin(), nums.end(), 0);\ncout << s << endl;\nreturn 0;\n}\n",
          "#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nint main() {\nvector<int> nums = {5, 5, 5, 5, 5};\nint s = accumulate(nums.begin(), nums.end(), 0);\ncout << s << endl;\nreturn 0;\n}\n"
